import numpy as np
def hough_lines(edges, tr=1, rr=1):
    thetas=np.deg2rad(np.arange(-90,90,tr))
    h,w=edges.shape;d=int(np.sqrt(h*h+w*w))
    rhos=np.arange(-d,d,rr);H=np.zeros((len(thetas),len(rhos)),dtype=int)
    ys,xs=np.where(edges>0)
    for y,x in zip(ys,xs):
        for ti,t in enumerate(thetas):
            r=x*np.cos(t)+y*np.sin(t);ri=int((r+d)/rr)
            if 0<=ri<len(rhos):H[ti,ri]+=1
    return H,thetas,rhos
def find_peaks(H,th=100):return np.argwhere(H>th)

from skimage.color import rgb2lab,lab2rgb
import numpy as np
def color_transfer(src,tgt):
    s=rgb2lab(src);t=rgb2lab(tgt);r=np.zeros_like(s)
    for c in range(3):
        sm,ss=np.mean(s[:,:,c]),np.std(s[:,:,c])
        tm,ts=np.mean(t[:,:,c]),np.std(t[:,:,c])
        r[:,:,c]=ts*(s[:,:,c]-sm)/ss+tm
    return lab2rgb(np.clip(r,0,100))

